func (q *Queries) ListAddons(ctx context.Context, arg ListAddonsParams) ([]Addon, error) {
	rows, err := q.db.Query(ctx, listAddons, arg.EventID, arg.OnlyActive)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Addon{}
	for rows.Next() {
		var i Addon
		if err := rows.Scan(
			&i.ID,
			&i.EventID,
			&i.Name,
			&i.Price,
			&i.Quota,
			&i.Sold,
			&i.Active,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

